<script lang="ts">
  import { onMount, tick } from 'svelte';
  import { fly, fade } from 'svelte/transition';
  import Coworkers from '../lib/Coworkers.svelte';
  import SidebarCoworkers from '../lib/SidebarCoworkers.svelte';
  import Office from '../lib/office/Office.svelte';
  import Sprite from '../lib/office/Sprite.svelte';
  import Icon from '../lib/ui/Icon.svelte';
  import { Terminal } from '@xterm/xterm';
  import { FitAddon } from '@xterm/addon-fit';
  import '@xterm/xterm/css/xterm.css';

  // Development uses Vite's same-origin proxy so the browser never needs a
  // separate cross-port connection to the local execution service.
  const api = import.meta.env.VITE_PIXEL_HARNESS_API || '/api/v1';
  let board: any[] = [], environments: any[] = [], decisions: any[] = [], selectedTaskId = '', historicalExecution: any = null, officeRuntime: any = null;
  $: viewExecution = execution && execution.employee_id === colleague?.employee_id && (!selectedTaskId || execution.task_id === selectedTaskId) ? execution : historicalExecution;
  async function mutate(path:string, body:any, method='PATCH'){try{await call(path,{method,body:JSON.stringify(body)});await load();}catch(e){error=(e as Error).message;}}
  function openPerson(person:any){focusedEmployee=person;selectedTaskId='';historicalExecution=null;panel='office';sidebarPreference=true;dock='activity';}
  async function openTask(task:any){selected=projects.find(p=>p.project_id===task.project_id);selectedTaskId=task.task_id;focusedEmployee=staff.find(p=>p.employee_id===task.employee_id)||null;historicalExecution=task.attempt;sidebarPreference=true;dock='activity';panel='office';try{threadTask=await call(`/tasks/${task.task_id}/thread`);threadOpen=true;}catch(e){error=(e as Error).message;}await tick();}
  let systemReduced=false;
  let compact=false, sidebarPreference: boolean | null=null;
  $: sidebarOpen=sidebarPreference ?? !compact;
  onMount(()=>{const media=matchMedia('(max-width: 1000px)');const update=()=>compact=media.matches;update();media.addEventListener('change',update);return()=>media.removeEventListener('change',update);});
  $: motionOff=Boolean(prefs.reduced_motion)||systemReduced;
  let poseOverrides:Record<string,string>={};
  let focusedEmployee: any = null, dock = 'activity', showSettings = false;
  let readiness: any = null, execution: any = null, launchPrompt = '', followUp = '', terminalHost: HTMLDivElement, xterm: Terminal | null = null, fit: FitAddon | null = null, terminalRendered = 0;
  let token = '', projects: any[] = [], staff: any[] = [], catalog:any={positions:[],skills:[],characters:[]}, prefs: any = { map_treatment: 'warm', reduced_motion: 0 }, inbox: any[] = [];
  let selected: any = null, panel = 'office', actor = { x: 12, y: 7 }, error = '', query = '', activeRequest: any = null, editing: any = null, folderPath = '', browse: any = null;
  let composerOpen=false, composerTask:any=null, composerEmployeeId='', composerInputs:any[]=[], composerFilePath='';
  let threadOpen=false, threadTask:any=null, threadMessage='', revisingDecisionId='';
  let quickTaskOpen=false, quickTaskEmployee:any=null, quickTaskObjective='', quickTaskFolderIds:string[]=[], quickTaskPrimaryFolderId='';
  let inviteOpen=false, inviteStep=1, inviteName='', invitePosition='fullstack-engineer', inviteCharacter='';
  let availableCharacters:any[]=[];
  $: availableCharacters=catalog.characters.filter((character:any)=>character.ready&&!character.owner_employee_id);
  $: inviteCharacterRecord=availableCharacters.find((character:any)=>character.character_id===inviteCharacter)||availableCharacters[0]||null;
  const roleSummaries:Record<string,string>={designer:'Shapes the product experience and visual quality.', 'frontend-engineer':'Builds browser interfaces and interaction details.', 'backend-engineer':'Builds service logic, data, and integrations.', 'fullstack-engineer':'Owns a feature across interface and service.', 'security-engineer':'Reviews risk, trust boundaries, and safeguards.', 'project-manager':'Keeps scope, decisions, and delivery moving.', marketing:'Turns product work into clear audience communication.'};
  async function call(path: string, options: RequestInit = {}) { const response = await fetch(`${api}${path}`, { ...options, headers: { 'Content-Type': 'application/json', ...(token ? { 'X-Pixel-Harness-Token': token } : {}), ...(options.headers || {}) } }); const value = await response.json(); if (!response.ok) throw new Error(`${value.error.code}: ${value.error.message}`); return value.data; }
  async function load(attempt = 0) {
    try {
      const result = await Promise.all([call('/projects'), call('/staff'), call('/staff/catalog'), call('/office/preferences'), call('/inbox'), call('/codex/readiness'), call('/executions/active'), call('/board'), call('/environments'), call('/decisions')]);
      [projects, staff, catalog, prefs, inbox, readiness, execution, board, environments, decisions] = result;
      selected = projects.find((project) => project.project_id === selected?.project_id) || projects.find((project) => project.status === 'active') || projects[0] || null;
      error = '';
    } catch (e) { if (attempt < 12) { await new Promise((resolve) => setTimeout(resolve, 250)); return load(attempt + 1); } error = (e as Error).message; }
  }
  onMount(() => { const found = new URLSearchParams(location.hash.slice(1)).get('token'); token = found || ''; const clientId=crypto.randomUUID(); const heartbeat=()=>call('/office/heartbeat',{method:'POST',body:JSON.stringify({client_id:clientId})}).then(value=>officeRuntime=value).catch(()=>{}); load(); void heartbeat(); const timer=window.setInterval(async()=>{try{const [nextExecution,nextBoard,nextStaff,nextEnvironments,nextInbox]=await Promise.all([call('/executions/active'),call('/board'),call('/staff'),call('/environments'),call('/inbox')]);execution=nextExecution;board=nextBoard;staff=nextStaff;environments=nextEnvironments;inbox=nextInbox;if(threadOpen&&threadTask?.task_id)threadTask=await call(`/tasks/${threadTask.task_id}/thread`);void heartbeat();writeTerminal();}catch{}},1000); const leaving=()=>{try{navigator.sendBeacon(`${api}/office/disconnect`,new Blob([JSON.stringify({client_id:clientId})],{type:'application/json'}));}catch{}};addEventListener('pagehide',leaving);return()=>{clearInterval(timer);removeEventListener('pagehide',leaving);leaving();}; });
  function terminalSurface(node: HTMLDivElement) { terminalHost=node; xterm=new Terminal({ theme:{background:'#1b1d25',foreground:'#d7d3c8',cursor:'#d7d3c8'}, fontSize:11, fontFamily:'ui-monospace, SFMono-Regular, Menlo, monospace', convertEol:true, scrollback:4000 }); fit=new FitAddon(); xterm.loadAddon(fit); xterm.open(node); fit.fit(); const resize=()=>{fit?.fit(); if(execution?.attempt_id) void call(`/executions/${execution.attempt_id}/resize`,{method:'POST',body:JSON.stringify({rows:xterm?.rows,cols:xterm?.cols})}).catch(()=>{});}; const observer=new ResizeObserver(resize);observer.observe(node);const input=xterm.onData((data)=>{if(viewExecution?.attempt_id===execution?.attempt_id&&execution?.terminal?.attached)void call(`/executions/${execution.attempt_id}/terminal-input`,{method:'POST',body:JSON.stringify({data})}).catch((e)=>error=e.message);});writeTerminal();return{destroy(){observer.disconnect();input.dispose();xterm?.dispose();xterm=null;fit=null;terminalRendered=0;}}; }
  function writeTerminal(){const text=viewExecution?.terminal?.terminal||'';if(xterm&&text.length>terminalRendered){xterm.write(text.slice(terminalRendered));terminalRendered=text.length;}if(xterm&&text.length<terminalRendered){xterm.reset();xterm.write(text);terminalRendered=text.length;}}
  async function launch(task:any){try{if(!task.assignments?.[0])throw new Error('Assign a colleague before launching.');const plan=task.plans?.find((item:any)=>item.status==='approved');if(!plan)throw new Error('PLAN_APPROVAL_REQUIRED: approve a plan version before launch.');error='';execution=await call('/executions',{method:'POST',body:JSON.stringify({task_id:task.task_id,employee_id:task.assignments[0].employee_id,plan_id:plan.plan_id,prompt:launchPrompt.trim()})});focusedEmployee=staff.find(p=>p.employee_id===execution.employee_id);selectedTaskId=task.task_id;historicalExecution=null;dock='terminal';sidebarPreference=true;panel='office';launchPrompt='';await load();}catch(e){const message=(e as Error).message;await load();error=message;}}
  async function stopExecution(){if(!execution?.attempt_id)return;try{await call(`/executions/${execution.attempt_id}/stop`,{method:'POST'});execution=null;historicalExecution=null;terminalRendered=0;await load();}catch(e){error=(e as Error).message;}}
  async function stopEmployee(){if(!focusedEmployee)return;try{await call(`/staff/${focusedEmployee.employee_id}/stop`,{method:'POST'});await load();}catch(e){error=(e as Error).message;}}
  async function toggleProjectPause(){if(!selected)return;try{await call(`/projects/${selected.project_id}/${selected.execution_state==='paused'?'resume':'pause'}`,{method:'POST'});await load();}catch(e){error=(e as Error).message;}}
  async function closeOffice(manual=false){try{await call(`/office/${manual?'stop':'close'}`,{method:'POST'});execution=null;await load();}catch(e){error=(e as Error).message;}}
  function openActiveTerminal(){focusedEmployee=staff.find(p=>p.employee_id===execution?.employee_id);selectedTaskId=execution?.task_id || '';historicalExecution=null;dock='terminal';sidebarPreference=true;panel='office';}
  async function setTreatment(map_treatment: 'warm' | 'cool' | 'editorial') { try { prefs = await call('/office/preferences', { method: 'PATCH', body: JSON.stringify({ map_treatment }) }); } catch (e) { error = (e as Error).message; } }
  async function setMotion(event: Event) { try { prefs = await call('/office/preferences', { method: 'PATCH', body: JSON.stringify({ reduced_motion: (event.currentTarget as HTMLInputElement).checked }) }); } catch (e) { error = (e as Error).message; } }
  async function createProject(event: SubmitEvent) { event.preventDefault(); const form = new FormData(event.currentTarget as HTMLFormElement); try { const created = await call('/projects', { method: 'POST', body: JSON.stringify({ name: form.get('name') }) }); await load(); selected = projects.find((project) => project.project_id === created.project_id) || selected; } catch (e) { error = (e as Error).message; } }
  function openInvite(){if(!availableCharacters.length){error='The current Studio has no unused curated character identities. Deactivate a teammate before inviting another.';return;}inviteName='';invitePosition='fullstack-engineer';inviteCharacter=availableCharacters[0].character_id;inviteStep=1;inviteOpen=true;}
  async function createStaff() { if(!inviteName.trim()){error='Give your teammate a name first.';return;}try { const created=await call('/staff', { method: 'POST', body: JSON.stringify({ name:inviteName.trim(), position_id:invitePosition,character_id:inviteCharacter }) }); await load();editing=staff.find(person=>person.employee_id===created.employee_id)||created;inviteOpen=false; } catch (e) { error = (e as Error).message; } }
  async function saveProfile(event:SubmitEvent){event.preventDefault();const form=new FormData(event.currentTarget as HTMLFormElement);try{await call(`/staff/${editing.employee_id}`,{method:'PATCH',body:JSON.stringify({name:form.get('name'),position_id:form.get('position_id'),character_id:form.get('character_id')})});await load();editing=staff.find(person=>person.employee_id===editing.employee_id);}catch(e){error=(e as Error).message;}}
  async function addSkill(event:SubmitEvent){event.preventDefault();const element=event.currentTarget as HTMLFormElement,form=new FormData(element);try{await call(`/staff/${editing.employee_id}/skills`,{method:'POST',body:JSON.stringify({skill_id:form.get('skill_id')||undefined,name:form.get('name')||undefined,instructions:form.get('instructions')||undefined})});element.reset();await load();editing=staff.find(person=>person.employee_id===editing.employee_id);}catch(e){error=(e as Error).message;}}
  async function toggleSkill(skill:any){try{await call(`/staff/${editing.employee_id}/skills/${skill.skill_id}`,{method:'PATCH',body:JSON.stringify({enabled:!skill.enabled})});await load();editing=staff.find(person=>person.employee_id===editing.employee_id);}catch(e){error=(e as Error).message;}}
  async function archive(action: 'archive' | 'reopen') { if (!selected) return; try { await call(`/projects/${selected.project_id}/${action}`, { method: 'POST' }); await load(); } catch (e) { error = (e as Error).message; } }
  async function saveDelivery(event:SubmitEvent){event.preventDefault();if(!selected)return;const form=new FormData(event.currentTarget as HTMLFormElement);try{await call(`/projects/${selected.project_id}/delivery`,{method:'PATCH',body:JSON.stringify({delivery_mode:form.get('delivery_mode'),default_branch:form.get('default_branch')||null,notes:form.get('notes')})});await load();}catch(e){error=(e as Error).message;}}
  async function setTaskDelivery(task:any,event:Event){const value=(event.currentTarget as HTMLSelectElement).value;try{await call(`/tasks/${task.task_id}/delivery`,{method:'PATCH',body:JSON.stringify({delivery_mode:value,destination:''})});await load();}catch(e){error=(e as Error).message;}}
  async function beginDelivery(task:any){try{await call(`/tasks/${task.task_id}/delivery`,{method:'POST'});await load();}catch(e){error=(e as Error).message;}}
  async function executeDelivery(task:any){try{await call(`/tasks/${task.task_id}/delivery/execute`,{method:'POST',body:JSON.stringify({confirmed:true})});await load();}catch(e){error=(e as Error).message;}}
  async function recordDelivery(task:any,attempt:any,outcome:any,status:'delivered'|'failed'){const destination=prompt(status==='delivered'?'Record the commit, branch, or PR destination:':'Record why this repository could not be delivered:')||'';if(!destination)return;try{await call(`/tasks/${task.task_id}/delivery/outcome`,{method:'POST',body:JSON.stringify({delivery_attempt_id:attempt.delivery_attempt_id,folder_id:outcome.folder_id,status,destination,detail:status==='failed'?destination:''})});await load();}catch(e){error=(e as Error).message;}}
  async function markProjectDone(){if(!selected)return;try{await call(`/projects/${selected.project_id}/done`,{method:'POST'});await load();}catch(e){error=(e as Error).message;}}
  async function attachNativeFolder() { if (!selected) return; try { const picked = await call('/folders/native-select', { method: 'POST' }); await call(`/projects/${selected.project_id}/folders`, { method: 'POST', body: JSON.stringify({ path: picked.path }) }); await load(); } catch (e) { const message=(e as Error).message; if(!message.startsWith('FOLDER_SELECTION_CANCELLED')) error = message; } }
  async function browsePath(path = '') { try { browse = await call(`/folders/browse?path=${encodeURIComponent(path)}`); } catch (e) { error = (e as Error).message; } }
  async function addTask(event: SubmitEvent) { event.preventDefault(); if (!selected) return; const form = new FormData(event.currentTarget as HTMLFormElement); try { await call('/tasks', { method: 'POST', body: JSON.stringify({ project_id: selected.project_id, title: form.get('title'), employee_id: form.get('employee_id') || undefined, folder_ids: form.getAll('folder_ids'), primary_folder_id: form.get('primary_folder_id') }) }); await load(); } catch (e) { error = (e as Error).message; } }
  function openComposer(employee?:any,task?:any){if(employee?.assignment){void openTask(board.find(item=>item.task_id===employee.assignment.task_id)||employee.assignment);return;}if(employee&&!task){quickTaskEmployee=employee;quickTaskObjective='';quickTaskFolderIds=[];quickTaskPrimaryFolderId='';quickTaskOpen=true;return;}composerTask=task||null;composerEmployeeId=task?.assignments?.[0]?.employee_id||employee?.employee_id||'';composerInputs=(task?.inputs||[]).map((item:any)=>({...item}));if(task){selected=projects.find(project=>project.project_id===task.project_id)||selected;}composerOpen=true;}
  async function startQuickTask(event:SubmitEvent){event.preventDefault();if(!selected||!quickTaskEmployee)return;const folders=selected.folders.filter((folder:any)=>folder.availability==='available'&&quickTaskFolderIds.includes(folder.folder_id));if(!folders.length||!quickTaskPrimaryFolderId||!quickTaskFolderIds.includes(quickTaskPrimaryFolderId)){error='Choose the folder scope and one primary folder before starting work.';return;}try{const task=await call('/tasks',{method:'POST',body:JSON.stringify({project_id:selected.project_id,title:quickTaskObjective,brief_text:quickTaskObjective,employee_id:quickTaskEmployee.employee_id,folder_ids:folders.map((folder:any)=>folder.folder_id),primary_folder_id:quickTaskPrimaryFolderId,inputs:[]})});quickTaskOpen=false;await load();await openTask(task);}catch(e){error=(e as Error).message;}}
  async function addComposerFiles(event:Event){const files=[...((event.currentTarget as HTMLInputElement).files||[])];for(const file of files){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));composerInputs=[...composerInputs,{input_id:crypto.randomUUID(),kind:file.type.startsWith('image/')?'image':'file',label:file.name,mime_type:file.type||'application/octet-stream',content_base64:btoa(binary),provenance:'browser file attachment',availability:'available'}];}(event.currentTarget as HTMLInputElement).value='';}
  function removeComposerInput(index:number){composerInputs=composerInputs.filter((_,itemIndex)=>itemIndex!==index);}
  function addFileReference(){const path=composerFilePath.trim();if(!path)return;composerInputs=[...composerInputs,{input_id:crypto.randomUUID(),kind:'file-reference',label:path.split('/').pop()||path,source_path:path,mime_type:null,provenance:'local file reference',availability:'available'}];composerFilePath='';}
  function relinkComposerInput(index:number){const path=composerFilePath.trim();if(!path)return;composerInputs=composerInputs.map((item,itemIndex)=>itemIndex===index?{...item,source_path:path,label:path.split('/').pop()||path,availability:'available',unavailable_reason:null}:item);composerFilePath='';}
  async function saveComposer(event:SubmitEvent){event.preventDefault();if(!selected)return;const form=new FormData(event.currentTarget as HTMLFormElement);const inputs=[...composerInputs];const paste=String(form.get('pasted_content')||'').trim();if(paste)inputs.push({input_id:crypto.randomUUID(),kind:'paste',label:'Pasted content',mime_type:'text/plain',content_base64:btoa(unescape(encodeURIComponent(paste))),provenance:'pasted in task composer'});for(const projectId of form.getAll('tag_project_ids'))inputs.push({input_id:crypto.randomUUID(),kind:'project',label:projects.find(project=>project.project_id===projectId)?.name||String(projectId),referenced_id:projectId,provenance:'tagged project context'});for(const employeeId of form.getAll('tag_employee_ids'))inputs.push({input_id:crypto.randomUUID(),kind:'employee',label:staff.find(person=>person.employee_id===employeeId)?.name||String(employeeId),referenced_id:employeeId,provenance:'tagged employee context'});for(const taskId of form.getAll('tag_task_ids'))inputs.push({input_id:crypto.randomUUID(),kind:'task',label:board.find(task=>task.task_id===taskId)?.title||String(taskId),referenced_id:taskId,provenance:'tagged task context'});
    try{const draft={project_id:selected.project_id,title:form.get('title'),brief_text:form.get('brief_text'),task_instructions:form.get('task_instructions'),employee_id:form.get('employee_id')||undefined,folder_ids:form.getAll('folder_ids'),primary_folder_id:form.get('primary_folder_id'),inputs};const task=composerTask?await call(`/tasks/${composerTask.task_id}/draft`,{method:'PATCH',body:JSON.stringify(draft)}):await call('/tasks',{method:'POST',body:JSON.stringify(draft)});composerOpen=false;composerTask=null;await load();await openTask(task);}catch(e){error=(e as Error).message;}}
  async function refreshThread(){if(!threadTask?.task_id)return;threadTask=await call(`/tasks/${threadTask.task_id}/thread`);}
  async function sendThreadMessage(save_as_team_agreement=false){if(!threadTask||!threadMessage.trim())return;try{threadTask=await call(`/tasks/${threadTask.task_id}/thread/messages`,{method:'POST',body:JSON.stringify({body:threadMessage,save_as_team_agreement})});threadMessage='';await load();}catch(e){error=(e as Error).message;}}
  async function proposeThreadPlan(event:SubmitEvent){event.preventDefault();if(!threadTask)return;const form=new FormData(event.currentTarget as HTMLFormElement);try{await call('/plans',{method:'POST',body:JSON.stringify({project_id:threadTask.project_id,task_id:threadTask.task_id,summary:form.get('summary'),milestones:String(form.get('milestones')||'').split('\n').filter(Boolean),acceptance:String(form.get('acceptance')||'').split('\n').filter(Boolean),dependencies:[]})});await load();await refreshThread();}catch(e){error=(e as Error).message;}}
  async function requestThreadDecision(event:SubmitEvent){event.preventDefault();if(!threadTask)return;const form=new FormData(event.currentTarget as HTMLFormElement);try{await call('/decisions',{method:'POST',body:JSON.stringify({project_id:threadTask.project_id,employee_id:threadTask.assignments?.[0]?.employee_id,kind:form.get('kind'),title:form.get('title'),recommendation:form.get('recommendation'),options:decisionOptions(form.get('options')),affected_task_ids:[threadTask.task_id],gated_task_ids:[threadTask.task_id]})});await load();await refreshThread();}catch(e){error=(e as Error).message;}}
  async function reviseThreadDecision(event:SubmitEvent,meeting:any){event.preventDefault();if(!threadTask)return;const form=new FormData(event.currentTarget as HTMLFormElement);try{await call(`/decisions/${meeting.decision_id}/revise`,{method:'POST',body:JSON.stringify({expected_version:meeting.current_version,feedback:form.get('feedback'),recommendation:form.get('recommendation'),options:decisionOptions(form.get('options')),affected_task_ids:[threadTask.task_id],gated_task_ids:[threadTask.task_id]})});revisingDecisionId='';await load();await refreshThread();}catch(e){error=(e as Error).message;}}
  async function complete(task: any) { try { await call(`/tasks/${task.task_id}/complete`, { method: 'POST' }); await load(); } catch (e) { error = (e as Error).message; } }
  async function saveDemo(event:SubmitEvent,task:any){event.preventDefault();const form=new FormData(event.currentTarget as HTMLFormElement);try{await call(`/tasks/${task.task_id}/demo`,{method:'PUT',body:JSON.stringify({setup_commands:String(form.get('setup_commands')||'').split('\n').map(item=>item.trim()).filter(Boolean),start_command:form.get('start_command'),readiness_command:form.get('readiness_command'),ports:String(form.get('ports')||'').split(',').map(Number).filter(Boolean),cleanup_command:form.get('cleanup_command'),known_gaps:form.get('known_gaps')})});await load();}catch(e){error=(e as Error).message;}}
  async function recordDemo(task:any){try{await call(`/tasks/${task.task_id}/demo/evidence`,{method:'POST',body:JSON.stringify({checks:[{command:'npm run check && npm test',result:'Passed in the reviewed fixture.',passed:true}],preview_note:'Runnable local Pixel Harness preview reviewed.'})});await load();}catch(e){error=(e as Error).message;}}
  async function acceptDemo(task:any,evidence:any){try{await call(`/tasks/${task.task_id}/demo/evidence/${evidence.evidence_id}/accept`,{method:'POST',body:JSON.stringify({accepted_by:'local user'})});await load();}catch(e){error=(e as Error).message;}}
  async function reopenTask(task: any) { try { await call(`/tasks/${task.task_id}/reopen`, { method: 'POST' }); await load(); } catch (e) { error = (e as Error).message; } }
  async function useAllProjectFolders(task: any) { const available=selected?.folders.filter((folder:any)=>folder.availability==='available')||[]; const primary=task.folders.find((folder:any)=>folder.is_primary)?.folder_id||available[0]?.folder_id; try { await call(`/tasks/${task.task_id}/folders`, { method: 'PATCH', body: JSON.stringify({ folder_ids: available.map((folder:any)=>folder.folder_id), primary_folder_id: primary }) }); await load(); } catch (e) { error = (e as Error).message; } }
  async function createPlan(event: SubmitEvent, task:any) { event.preventDefault(); const form = new FormData(event.currentTarget as HTMLFormElement); try { await call('/plans',{method:'POST',body:JSON.stringify({project_id:selected.project_id,task_id:task.task_id,summary:form.get('summary'),milestones:String(form.get('milestones')||'').split('\n').filter(Boolean),acceptance:String(form.get('acceptance')||'').split('\n').filter(Boolean),dependencies:[]})});await load(); } catch(e){error=(e as Error).message;} }
  async function approvePlan(plan:any) { try { await call(`/plans/${plan.plan_id}/approve`,{method:'POST',body:JSON.stringify({approved_by:'local user'})});await load(); } catch(e){error=(e as Error).message;} }
  function decisionOptions(value:FormDataEntryValue|null){return String(value||'').split('\n').map(line=>line.trim()).filter(Boolean).map((line,index)=>{const [name,tradeoff,preview]=line.split('|').map(part=>part.trim());return{name:name||`Option ${index+1}`,tradeoff:tradeoff||'No tradeoff supplied.',preview:preview||['moss','clay','navy'][index%3]};});}
  async function createDecision(event:SubmitEvent){event.preventDefault();if(!selected)return;const element=event.currentTarget as HTMLFormElement,form=new FormData(element);try{await call('/decisions',{method:'POST',body:JSON.stringify({project_id:selected.project_id,employee_id:form.get('employee_id')||undefined,kind:form.get('kind'),title:form.get('title'),recommendation:form.get('recommendation'),options:decisionOptions(form.get('options')),affected_task_ids:form.getAll('affected_task_ids'),gated_task_ids:form.getAll('gated_task_ids')})});element.reset();await load();}catch(e){error=(e as Error).message;}}
  async function reviseDecision(event:SubmitEvent,meeting:any){event.preventDefault();const form=new FormData(event.currentTarget as HTMLFormElement);try{await call(`/decisions/${meeting.decision_id}/revise`,{method:'POST',body:JSON.stringify({expected_version:meeting.current_version,feedback:form.get('feedback'),recommendation:form.get('recommendation'),options:decisionOptions(form.get('options')),affected_task_ids:form.getAll('affected_task_ids'),gated_task_ids:form.getAll('gated_task_ids')})});await load();}catch(e){error=(e as Error).message;}}
  async function approveDecision(meeting:any){try{await call(`/decisions/${meeting.decision_id}/approve`,{method:'POST',body:JSON.stringify({version:meeting.current_version,approved_by:'local user'})});await load();}catch(e){error=(e as Error).message;}}
  async function saveGuidance(event: SubmitEvent, taskId?: string, replaces?: string) { event.preventDefault(); const form=new FormData(event.currentTarget as HTMLFormElement); try { await call('/guidance',{method:'POST',body:JSON.stringify({project_id:selected.project_id,task_id:taskId,content:form.get('content'),provenance:form.get('provenance'),replaces_guidance_id:replaces})}); await load(); } catch(e){error=(e as Error).message;} }
  async function retireGuidance(guidance:any) { try { await call(`/guidance/${guidance.guidance_id}/retire`,{method:'POST'});await load(); } catch(e){error=(e as Error).message;} }
  async function sendFollowUp() { if(!execution||!followUp.trim())return; try { execution=await call(`/executions/${execution.attempt_id}/messages`,{method:'POST',body:JSON.stringify({content:followUp})});followUp='';await load(); } catch(e){error=(e as Error).message;} }
  async function createRealRequest(event: SubmitEvent) { event.preventDefault();const form=new FormData(event.currentTarget as HTMLFormElement);try {await call('/inbox/requests',{method:'POST',body:JSON.stringify({kind:form.get('kind'),summary:form.get('summary'),detail:form.get('detail'),blocks:form.get('blocks')})});await load();}catch(e){error=(e as Error).message;} }
  async function answerRequest(request:any,event:SubmitEvent) {event.preventDefault();const form=new FormData(event.currentTarget as HTMLFormElement);try{await call(`/inbox/${request.request_id}/answer`,{method:'POST',body:JSON.stringify({response:form.get('response')})});activeRequest=null;await load();}catch(e){error=(e as Error).message;}}
  async function answerThreadRequest(request:any,event:SubmitEvent){event.preventDefault();const form=new FormData(event.currentTarget as HTMLFormElement);try{await call(`/inbox/${request.request_id}/answer`,{method:'POST',body:JSON.stringify({response:form.get('response')})});await load();await refreshThread();}catch(e){error=(e as Error).message;}}
  async function addNotice() { try { await call('/inbox/requests', { method: 'POST', body: JSON.stringify({ kind: 'clarification', summary: 'Codex needs clarification', detail: 'Please clarify the intended implementation direction before continuing.', blocks: 'The active Codex session is waiting for this direction.' }) }); await load(); } catch (e) { error = (e as Error).message; } }
  async function resolveNotice(request: any) { try { await call(`/inbox/${request.request_id}/answer`, { method: 'POST', body: JSON.stringify({ response: request.kind === 'clarification' ? 'Choose alpha. Continue with the approved bounded task.' : 'Acknowledged from the office inbox.' }) }); activeRequest = null; await load(); } catch (e) { error = (e as Error).message; } }
  onMount(()=>{const media=matchMedia('(prefers-reduced-motion: reduce)');systemReduced=media.matches;const change=()=>systemReduced=media.matches;media.addEventListener('change',change);return()=>media.removeEventListener('change',change);});
  function closePanel(){panel='office';}
  function focusSurface(node:HTMLElement, anchored=false){
    const trigger=document.activeElement as HTMLElement;
    if(anchored){const r=trigger?.getBoundingClientRect();const width=Math.min(280,innerWidth-24);node.style.width=`${width}px`;node.style.left=`${Math.max(12,Math.min(innerWidth-width-12,r?.right+10||12))}px`;node.style.top=`${Math.max(70,Math.min(innerHeight-220,(r?.top||80)-20))}px`;}
    let alive=true;
    tick().then(()=>{if(alive)(node.querySelector('button') as HTMLElement || node).focus({preventScroll:true});});
    const trap=(event:KeyboardEvent)=>{if(event.key!=='Tab')return;const items=[...node.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,[tabindex="0"]')].filter(item=>item.getClientRects().length);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}};
    node.addEventListener('keydown',trap);
    return {destroy(){alive=false;node.removeEventListener('keydown',trap);if(trigger?.isConnected)trigger.focus({preventScroll:true});}};
  }
  function shortcut(event: KeyboardEvent) {
    if(event.key==='Escape'){event.preventDefault();if(showSettings)showSettings=false;else if(panel!=='office')closePanel();return;}
    if ((event.target as HTMLElement)?.closest('input,select,textarea,[role="application"]') || event.metaKey || event.ctrlKey || event.altKey) return;
    const next: Record<string,string> = {b:'board',o:'office',p:'projects',t:'coworkers',i:'inbox',d:'demos'};
    if (next[event.key.toLowerCase()]) { event.preventDefault(); showSettings=false;panel = next[event.key.toLowerCase()]; }
  }
  $: visibleProjects = projects.filter((project) => project.name.toLowerCase().includes(query.toLowerCase()));
  $: colleague = staff.find(person => person.employee_id === focusedEmployee?.employee_id) || null;
  $: pending = inbox.filter((request) => request.status === 'pending');
  $: resolvedRequests = inbox.filter((request) => request.status === 'resolved');
  $: pendingByEmployee = Object.fromEntries(pending.filter((request:any) => request.employee_id).map((request:any) => [request.employee_id, request]));
  $: if (panel==='inbox' && activeRequest?.task_id && !threadOpen) { void openTask(board.find((task:any)=>task.task_id===activeRequest.task_id)||activeRequest); }
  function readableRequest(request:any){return String(request.detail||'').replace(/\[PIXEL_REQUEST\][\s\S]*$/i,'').trim()||String(request.blocks||'');}
  $: projectDecisions = decisions.filter((meeting) => meeting.project_id === selected?.project_id);
</script>

<svelte:window onkeydown={shortcut} />
<svelte:head><meta name="theme-color" content="#111827" /><title>Pixel Harness · office</title></svelte:head>
<main class:reduce-motion={Boolean(prefs.reduced_motion)} class={`treatment-${prefs.map_treatment}`}>
  <header class="appbar">
    <nav aria-label="Office navigation">
      {#each [{id:'coworkers',label:'Team',key:'T'},{id:'board',label:'Task board',key:'B'},{id:'office',label:'Studio',key:'O'},{id:'inbox',label:'Inbox',key:'I'},{id:'projects',label:'Projects',key:'P'}] as item}
        <button class:active={item.id==='coworkers'?panel==='coworkers':panel===item.id} onclick={() => { if(item.id==='coworkers'){focusedEmployee=null;panel='coworkers';}else panel=item.id; }} aria-label={item.label} title={`${item.label} (${item.key})`}><Icon name={item.id==='coworkers'?'roster':item.id==='board'?'history':item.id}/><span class="nav-label">{item.label}</span>{#if item.id==='inbox'&&pending.length}<b>{pending.length}</b>{/if}</button>
      {/each}
      <button class:active={showSettings} aria-label="Room settings" title="Room settings" onclick={()=>showSettings=!showSettings}><Icon name="settings"/><span class="nav-label">Settings</span></button>
    </nav>
  </header>
  {#if error}<p class="error" role="alert">{error}</p>{/if}

    <section class="office-layout" class:sidebar-closed={!sidebarOpen} class:behind-panel={panel!=='office'} inert={panel!=='office'||showSettings}>
      <section class="office-stage" class:panel-visible={sidebarOpen}>
        <button class="sidebar-toggle" aria-label={sidebarOpen ? 'Hide coworker panel' : 'Show coworker panel'} aria-expanded={sidebarOpen} aria-controls="coworker-panel" onclick={()=>sidebarPreference=!sidebarOpen}><Icon name="roster"/><span>Coworkers</span><Icon name={sidebarOpen?'collapse':'expand'}/></button>
        <Office {poseOverrides} {pendingByEmployee} active={panel==='office'&&!showSettings} staff={staff.filter(p=>p.environment?.kind==='local')} reduced={Boolean(prefs.reduced_motion)} selectedId={colleague?.employee_id} navigate={(next, person) => { if(person) {openPerson(person);} else panel=next; }} openRequest={(request,person)=>{if(request.task_id){void openTask(board.find(task=>task.task_id===request.task_id)||request);return;}focusedEmployee=person;activeRequest=request;panel='inbox';}} />
        <div class="world-bar"><span>Company Studio</span></div>
        <button class="mail-tray" onclick={()=>panel='inbox'} aria-label={`Open inbox${pending.length?`, ${pending.length} pending requests`:''}`}><Icon name="inbox"/><span>Inbox</span>{#if pending.length}<b>{pending.length}</b>{/if}</button>
      </section>
      <aside class="studio-sidebar" id="coworker-panel" hidden={!sidebarOpen}>
        <section class="dialogue-frame">
          <div class="frame-bar"><span class="frame-icon"><Icon name={colleague?'expand':'roster'}/></span>{#if colleague}<button class="back-to-coworkers" onclick={()=>{focusedEmployee=null;selectedTaskId='';historicalExecution=null;dock='activity';}}>‹ Coworkers</button><button class="back-to-coworkers" onclick={stopEmployee}>Stop employee</button>{/if}<span class="frame-caption">{colleague ? 'Colleague' : 'Coworkers'}</span><span class="frame-dots" aria-hidden="true">▪ ▪</span><button class="sidebar-close" aria-label="Collapse coworker panel" onclick={()=>sidebarPreference=false}><Icon name="collapse"/></button></div>
          {#if !colleague}
            <SidebarCoworkers {staff} {board} {openPerson}/>
          {:else}
          <div class="conversation">
            {#key colleague?.employee_id}<div class="speaker" in:fade={{duration:motionOff?0:140}}><div class="portrait-crop"><Sprite character kind="bust" recipe={colleague?.appearance_recipe || {}}/></div><div><h1>{colleague?.name || 'Welcome in.'}</h1><p>{colleague?.title || 'Make yourself at home'}</p><small>{colleague?.environment?.kind==='coder'?'Remote · Coder · not connected':'In office · Local'} · {board.find(t=>t.task_id===colleague?.assignment?.task_id)?.working_state || 'Available'}</small></div></div>{/key}
            {#key colleague?.employee_id}<div class="dialogue-body">
              <div class="speech">{#if viewExecution}<small>Session {viewExecution.session_id} · {viewExecution.continuation_state}</small>{/if}{viewExecution ? `${viewExecution.employee_name} owns the Codex session for ${viewExecution.task_title}.` : colleague?.assignment ? `Current assignment: ${colleague.assignment.task_title}` : colleague ? `${colleague.name} is available. Open your project to plan their next assignment.` : 'Start with a project and bring your first colleague into the office.'}</div>
              {#if colleague?.active_assignments?.length || colleague?.assignment}<section class="assignment-actions" aria-label={`${colleague?.name}'s active tasks`}><p class="bubble-label">Active work</p>{#each colleague?.active_assignments?.length ? colleague.active_assignments : [colleague.assignment] as assignment}<button onclick={()=>openTask(board.find(task=>task.task_id===assignment.task_id)||assignment)}><span><strong>{assignment.task_title}</strong><small>{board.find(task=>task.task_id===assignment.task_id)?.working_state || 'Open task'} · scope and decision status</small></span><b aria-hidden="true">›</b></button>{/each}</section>{:else}<button class="speech choice" onclick={()=>openComposer(colleague)}>Assign new task<small>Choose the scope before work begins</small><span>▶</span></button>{/if}
              <div class="speech history-bubble"><p class="bubble-label">{colleague ? 'Assignment history' : 'The office'}</p>{#if colleague?.history?.some((item:any)=>item.ended_at)}{#each colleague.history.filter((item:any)=>item.ended_at).slice(0,1) as assignment}<p>{assignment.task_title}<small>{assignment.ended_at ? 'Completed · colleague released' : 'Current assignment'}</small></p>{/each}{:else}<p>{colleague ? 'No completed assignments yet.' : 'Projects, people and their history are kept together on this computer.'}</p>{/if}</div>
              <div class="speech project-bubble"><span class="bubble-label">Work context</span><p>{selected?.name || 'No project selected'}<small>{selected?.tasks?.filter((task:any)=>task.status!=='complete').length || 0} open tasks · company-wide Studio</small></p></div>{#if colleague?.environment?.kind==='local'}<div class="pose-controls" aria-label="Coworker room activity"><span>In the Studio</span>{#each [{id:'seated',label:'At desk'},{id:'walking',label:'Walk'},{id:'sleeping',label:'Rest'}] as pose}<button title="Room animation only; does not change task execution" class:chosen={poseOverrides[colleague.employee_id]===pose.id} onclick={()=>poseOverrides={...poseOverrides,[colleague.employee_id]:pose.id}}>{pose.label}</button>{/each}</div>{/if}<div class="dialogue-options"><button onclick={()=>{editing=colleague;panel='roster';}}><span>▸</span>{colleague ? 'Profile & skills' : 'Add a colleague'}</button><button onclick={()=>panel='inbox'}><span>▸</span>{pending.length ? `${pending.length} request${pending.length===1?'':'s'} in the mailbox` : 'Open the mailbox'}</button><button onclick={()=>panel='projects'}><span>▸</span>{selected?.name || 'Your projects'}</button></div>
            </div>{/key}
          </div>
          {/if}
        </section>
        {#if viewExecution}<section class="terminal-frame execution-dock"><div class="dock-title"><Icon name="terminal"/><span>{viewExecution.employee_name} · {viewExecution.task_title}</span></div><div class="dock-content" in:fade={{duration:motionOff?0:120}}>{#if viewExecution.terminal?.attached}<div class="native-terminal" use:terminalSurface role="application" aria-label="Native Codex terminal"></div><div class="terminal-controls"><span>Native Codex terminal</span><button disabled={viewExecution?.attempt_id !== execution?.attempt_id} onclick={stopExecution}>Stop execution</button></div><form class="follow-up" onsubmit={(event)=>{event.preventDefault();sendFollowUp();}}><input bind:value={followUp} placeholder="Send a durable follow-up" aria-label="Follow-up message"/><button disabled={!followUp.trim() || viewExecution?.attempt_id !== execution?.attempt_id}>Send</button></form>{:else}<p class="log-muted">Saved session history · no live terminal is attached.</p><p class="log-muted">This record is reviewable context, not a claim of current Codex activity.</p>{/if}</div></section>{/if}
      </aside>
    </section>
  {#if panel !== 'office'}
    <button class="panel-backdrop" aria-label="Close panel" onclick={closePanel} transition:fade={{duration:motionOff?0:120}}></button>
    <div class="panel-sheet" role="dialog" aria-modal="true" aria-label={panel==='coworkers'?'Coworkers':panel==='board'?'Task board':panel==='projects'?'Projects':panel==='roster'?'Roster':'Inbox'} tabindex="-1" use:focusSurface in:fly={{x:8,duration:motionOff?0:160}} out:fade={{duration:motionOff?0:100}}>
      <button class="close-sheet" aria-label="Return to office" onclick={closePanel}><Icon name="close"/></button>
  {#if panel === 'board' || panel === 'coworkers'}
    <Coworkers mode={panel} {staff} {board} {projects} {environments} {openPerson} {openTask} {mutate}/>
  {:else if panel === 'projects'}
    <section class="drawer-layout">
      <aside class="list-pane"><p class="eyebrow">DIRECT ACCESS</p><h1>Projects</h1><input bind:value={query} placeholder="Search projects" aria-label="Search projects" /> <form onsubmit={createProject}><input name="name" placeholder="New project name" required /><button>Create</button></form>{#each visibleProjects as project}<button class="project-row" class:chosen={project.project_id === selected?.project_id} onclick={() => { selected = project; panel = 'office'; }}><strong>{project.name}</strong><small>{project.status} · {project.folders.length} folders · {project.tasks.length} tasks</small></button>{/each}</aside>
      <section class="detail-pane">{#if selected}<div class="detail-head"><div><p class="eyebrow">PROJECT ROOM</p><h1>{selected.name}</h1><p>{selected.status === 'archived' ? 'Archived records remain readable; staff have been released.' : `Release state: ${selected.release?.state || 'active'}. Accepted demos and delivery remain separate.`}</p></div><div><button onclick={()=>openComposer()}>New task brief</button>{#if selected.status==='active'}<button onclick={markProjectDone} disabled={selected.release?.state==='done'}>{selected.release?.state==='done'?'Project done':'Mark project done'}</button> <button onclick={() => archive('archive')} disabled={selected.release?.state!=='done'}>Archive project</button>{:else}<button onclick={() => archive('reopen')}>Reopen project</button>{/if}</div></div><div class="columns"><section><h2>Delivery defaults</h2><form class="skill-form" onsubmit={saveDelivery}><label>Mode <select name="delivery_mode" value={selected.delivery?.delivery_mode || 'review'}><option value="review">Review only</option><option value="local">Local changes</option><option value="branch">Branch / commit</option><option value="pull_request">Pull request</option><option value="merge">Authorized merge</option></select></label><label>Default branch <input name="default_branch" value={selected.delivery?.default_branch || ''} placeholder="main" /></label><label>Prerequisites / notes <textarea name="notes">{selected.delivery?.notes || ''}</textarea></label><button>Save delivery defaults</button></form><p class="capability-note">Every delivery runs only after explicit confirmation, from a clean Git baseline. Existing dirty work is preserved. Pull requests require an authenticated GitHub CLI and an `origin` remote; merge and publishing remain unavailable.</p></section><section><h2>Attached folders</h2><button onclick={attachNativeFolder}>Choose local folder…</button><p class="empty">Choose task scope explicitly in each brief.</p><ul>{#each selected.folders as folder}<li><code>{folder.display_path}</code><small>{folder.availability}</small></li>{/each}</ul></section><section><h2>Tasks</h2><ul>{#each selected.tasks as task}<li class="task-row" id={`task-${task.task_id}`}><strong>{task.title}</strong><small>{board.find(t=>t.task_id===task.task_id)?.working_state || task.status} · {task.assignments.map((assignment: any) => assignment.employee_name).join(', ') || 'unassigned'} · {task.inputs.length} inputs</small><button onclick={()=>openComposer(undefined,task)}>Edit task brief</button><label>Delivery override <select onchange={(event)=>setTaskDelivery(task,event)} value={task.delivery?.override?.delivery_mode || ''}><option value="" disabled>Use project default</option><option value="local">Local changes</option><option value="branch">Branch / commit</option><option value="pull_request">Pull request</option><option value="merge">Authorized merge</option></select></label>{#if task.demo?.evidence?.some((e:any)=>e.status==='accepted')}<button onclick={()=>beginDelivery(task)}>Prepare delivery</button> <button onclick={()=>executeDelivery(task)}>Confirm delivery</button>{:else}<p class="execution-status">Delivery waits for accepted demo evidence.</p>{/if}{#each task.delivery?.attempts?.slice(0,1) || [] as attempt}<p class="execution-status">Delivery {attempt.status} · {attempt.mode}</p>{#each attempt.outcomes as outcome}<div class="block"><code>{task.folders.find((folder:any)=>folder.folder_id===outcome.folder_id)?.display_path}</code> · {outcome.status} {#if outcome.destination}<small>{outcome.destination}</small>{/if}{#if outcome.status!=='delivered'}<button onclick={()=>recordDelivery(task,attempt,outcome,'delivered')}>Record external delivery</button> <button class="secondary" onclick={()=>recordDelivery(task,attempt,outcome,'failed')}>Record failed</button>{/if}</div>{/each}{/each}{#if task.status === 'complete'}<p class="execution-status">This task is complete. Reopen it to restore its previous assignment.</p><button onclick={() => reopenTask(task)}>Reopen task</button>{:else}<p class="execution-status">{board.find(t=>t.task_id===task.task_id)?.blocking_reason || 'Ready for explicit launch.'}</p>{#if task.inputs.some((input:any)=>input.availability!=='available')}<p class="execution-status">Launch unavailable: remove or resolve inaccessible inputs.</p>{/if}<label class="execution-request">Explicit Codex request <textarea bind:value={launchPrompt} disabled={!task.assignments.length || task.folders.length < 2} placeholder="Describe the approved work to launch."></textarea></label>{#if !task.assignments.length}<p class="execution-status">Launch unavailable: assign a colleague in the task brief.</p>{:else if task.folders.length < 2}<p class="execution-status">Launch unavailable: this task has {task.folders.length} selected folder. Codex execution requires at least two.</p>{:else if readiness?.state !== 'ready'}<p class="execution-status">Launch unavailable: {readiness?.detail || 'Codex is not ready.'}</p>{/if}<button disabled={Boolean(execution)||readiness?.state!=='ready'||!task.assignments.length||task.folders.length<2||task.inputs.some((input:any)=>input.availability!=='available')} onclick={() => launch(task)}>{execution ? 'Another execution owns Codex' : 'Launch Codex'}</button><button class="secondary" onclick={() => complete(task)}>Complete task (simulation)</button>{/if}</li>{/each}</ul></section></div>{:else}<p class="empty">Create your first project to open its room.</p>{/if}</section>
      {#if execution}<button class="active-terminal-cta" onclick={openActiveTerminal}>Open active Codex terminal</button>{/if}
    </section>
  {:else if panel === 'demos'}
    <section class="inbox-shell"><header><div><p class="eyebrow">SIT-DOWN DEMO</p><h1>Reviewable demos</h1><p>Evidence is tied to the exact repository revision and workspace fingerprint. Acceptance never publishes or delivers work.</p></div></header>{#each projects as project}{#each project.tasks as task}{#if task.demo}<article class="meeting-card" class:approved={task.demo.evidence.some((evidence:any)=>evidence.status==='accepted')}><span class="version-pill">{task.demo.evidence.some((evidence:any)=>evidence.status==='fresh')?'ready for review':'recipe'}</span><h2>{task.title}</h2><p><strong>Preview:</strong> {task.demo.start_command}</p><p><strong>Readiness:</strong> {task.demo.readiness_command}</p><p><strong>Owned ports:</strong> {task.demo.ports.join(', ') || 'none'}</p>{#each task.demo.evidence as evidence}<div class="block"><strong>{evidence.status}</strong> · {evidence.preview_note}<small>{evidence.checks.map((check:any)=>`${check.command}: ${check.result}`).join(' · ')}</small>{#if evidence.stale_reason}<small>{evidence.stale_reason}</small>{/if}</div>{/each}<p class="metadata">Known gaps: {task.demo.known_gaps || 'None recorded.'}</p></article>{/if}{/each}{/each}<p class="empty">Press P to save a task recipe through the local API; no demo evidence is treated as delivery.</p></section>
  {:else if panel === 'roster'}
    <section class="drawer-layout roster-layout"><aside class="list-pane roster-list"><p class="eyebrow">COMPANY ROSTER</p><div class="roster-title"><div><h1>Teammates</h1><p>{staff.length} active · {availableCharacters.length} curated character{availableCharacters.length===1?'':'s'} available</p></div><button class="invite-cta" onclick={openInvite}><Icon name="add"/>Invite teammate</button></div><p class="roster-intro">Each teammate has a fixed, curated Studio identity. Choose a name and the work they should lead; skills stay optional.</p>{#each staff as person}<button class="person-row" class:chosen={editing?.employee_id === person.employee_id} onclick={() => editing = person}><span class="roster-sprite"><Sprite character kind="standing" recipe={person.appearance_recipe}/></span><span><strong>{person.name}</strong><small>{person.title} · {person.environment?.kind==='coder'?'Remote':'In office'} · {person.assignment ? `Assigned to ${person.assignment.task_title}` : 'Available'}</small></span></button>{:else}<p class="empty">No teammates yet. Invite one when you are ready to give work a home.</p>{/each}</aside><section class="detail-pane">{#if editing}<p class="eyebrow">TEAMMATE PROFILE</p><h1>{editing.name}</h1><div class="avatar-preview"><div class="editor-sprite"><Sprite character kind="standing" recipe={editing.appearance_recipe}/></div><span>Curated Studio identity · {editing.character_id.replace('studio-character-','')}</span></div><form onsubmit={saveProfile} class="recipe"><label>Name<input name="name" value={editing.name} required/></label><label>Role<select name="position_id" value={editing.position_id}>{#each catalog.positions as position}<option value={position.position_id}>{position.name}</option>{/each}</select></label><label>Studio identity<select name="character_id" value={editing.character_id}>{#each catalog.characters.filter((character:any)=>character.ready&&(!character.owner_employee_id||character.owner_employee_id===editing.employee_id)) as character}<option value={character.character_id}>{character.character_id.replace('studio-character-','Character ')}</option>{/each}</select></label><button>Save profile</button></form><p class="capability-note">Skills are optional instructions, never hidden permissions or access. Workplace and personal skills are managed separately from role selection.</p>{#if editing.skills.length}<h2>Personal skills</h2><ul>{#each editing.skills as skill}<li><strong>{skill.name}</strong><small>{skill.kind} · {skill.enabled?'enabled':'disabled'}</small><button onclick={()=>toggleSkill(skill)}>{skill.enabled?'Disable':'Enable'}</button></li>{/each}</ul>{:else}<p class="empty">No personal skills added. This teammate can still be assigned work.</p>{/if}<h2>Assignment history</h2><ul>{#each editing.history as assignment}<li><strong>{assignment.task_title}</strong><small>{assignment.project_name} · {assignment.ended_at ? 'released' : 'active assignment'}</small></li>{:else}<li>No assignments yet.</li>{/each}</ul>{:else}<p class="empty">Select a teammate to see their role, optional skills, and work history.</p>{/if}</section></section>
  {:else}
    <section class="inbox-shell"><header><div><p class="eyebrow">OFFICE MAILBOX</p><h1>Needs your attention</h1><p>Only open questions are here. Completed conversations stay in history.</p></div></header><div class="inbox-grid"><section class="request-list"><h2>{pending.length ? `${pending.length} open request${pending.length===1?'':'s'}` : 'All caught up'}</h2>{#each pending as request}<button class:chosen={activeRequest?.request_id === request.request_id} onclick={() => activeRequest = request}><b>{request.kind}</b><strong>{request.summary}</strong><small>{request.project_name} · {request.employee_name || 'Office'}</small></button>{:else}<p class="empty">No coworker is waiting on you.</p>{/each}</section><section class="request-detail">{#if activeRequest && activeRequest.status==='pending'}<p class="eyebrow">{activeRequest.employee_name || 'Office'} needs your input</p><h2>{activeRequest.summary}</h2><p>{readableRequest(activeRequest)}</p><div class="block"><strong>This is waiting on you</strong><p>{activeRequest.blocks}</p></div><p class="metadata">{activeRequest.project_name} · {activeRequest.task_title || 'General office question'}</p>{#if activeRequest.decision_id}<button onclick={() => { selected=projects.find(project=>project.project_id===activeRequest.project_id)||selected;panel='projects'; }}>Review the decision</button>{:else}<form class="follow-up" onsubmit={(event)=>answerRequest(activeRequest,event)}><input name="response" placeholder="Reply to continue the work" aria-label="Reply to coworker" required/><button>Send reply</button></form>{/if}<button class="secondary" onclick={() => { if (activeRequest.task_id) { selected = projects.find(project => project.project_id === activeRequest.project_id) || selected; panel = 'projects'; } else panel = 'office'; }}>Open related {activeRequest.task_id ? 'task' : 'office'}</button>{:else}<p class="empty">Choose an open request to respond.</p>{/if}</section></div><section class="history"><h2>Conversation history</h2>{#each resolvedRequests.slice(0,5) as request}<button class="history-row" onclick={()=>activeRequest=request}><strong>{request.summary}</strong><small>{request.employee_name || 'Office'} · resolved</small></button>{:else}<p>No completed conversations yet.</p>{/each}</section></section>
  {/if}
    </div>
  {/if}
  {#if quickTaskOpen && quickTaskEmployee}
    <button class="composer-backdrop" aria-label="Close task start" onclick={()=>quickTaskOpen=false}></button>
    <div class="quick-task" role="dialog" aria-modal="true" aria-label={`Start task with ${quickTaskEmployee.name}`} tabindex="-1" use:focusSurface>
      <header><div><p class="eyebrow">START WITH {quickTaskEmployee.name.toUpperCase()}</p><h1>What should they accomplish?</h1><p>Write the objective in one sentence. You can add context after the thread opens.</p></div><button aria-label="Close task start" onclick={()=>quickTaskOpen=false}><Icon name="close"/></button></header>
      <form onsubmit={startQuickTask}><textarea bind:value={quickTaskObjective} placeholder="One-sentence objective" required></textarea><fieldset><legend>Explicit folder scope</legend>{#each selected?.folders.filter((folder:any)=>folder.availability==='available') || [] as folder}<label><input type="checkbox" value={folder.folder_id} checked={quickTaskFolderIds.includes(folder.folder_id)} onchange={(event)=>{const checked=(event.currentTarget as HTMLInputElement).checked;quickTaskFolderIds=checked?[...quickTaskFolderIds,folder.folder_id]:quickTaskFolderIds.filter(id=>id!==folder.folder_id);if(!checked&&quickTaskPrimaryFolderId===folder.folder_id)quickTaskPrimaryFolderId='';}}/> {folder.display_path}</label>{#if quickTaskFolderIds.includes(folder.folder_id)}<label><input type="radio" name="quick_primary_folder" value={folder.folder_id} checked={quickTaskPrimaryFolderId===folder.folder_id} onchange={()=>quickTaskPrimaryFolderId=folder.folder_id}/> primary</label>{/if}{/each}</fieldset><p>{selected?.name || 'No project selected'} · selected folders become the task scope; nothing else is implied.</p><footer><button type="button" onclick={()=>quickTaskOpen=false}>Cancel</button><button disabled={!quickTaskObjective.trim()||!quickTaskFolderIds.length||!quickTaskPrimaryFolderId}>Start task thread</button></footer></form>
    </div>
  {/if}
  {#if threadOpen && threadTask}
    <button class="composer-backdrop" aria-label="Close task thread" onclick={()=>threadOpen=false}></button>
    <div class="task-thread" role="dialog" aria-modal="true" aria-label={`Task thread: ${threadTask.title}`} tabindex="-1" use:focusSurface>
      <header><div><p class="eyebrow">TASK WORKSPACE · {threadTask.assignments?.[0]?.employee_name || 'UNASSIGNED'}</p><h1>{threadTask.title}</h1><p>{threadTask.thread.waiting_on ? `Waiting: ${threadTask.thread.waiting_on}` : 'No action is waiting on you.'}</p></div><div class="workspace-actions"><button class="workspace-session" onclick={()=>{threadOpen=false;dock='terminal';}}>{#if viewExecution?.terminal?.attached}<span>Open native terminal</span><small>Attached live session</small>{:else}<span>Open session history</span><small>Reviewable record · not live</small>{/if}</button>{#if !['complete','cancelled'].includes(threadTask.status)}<button class="workspace-cancel" onclick={async()=>{if(!confirm(`Cancel “${threadTask.title}”? This stops its current task flow.`))return;await call(`/tasks/${threadTask.task_id}/cancel`,{method:'POST'});threadOpen=false;await load();}}>Cancel task</button>{:else}<button class="workspace-reopen" onclick={async()=>{await call(`/tasks/${threadTask.task_id}/reopen`,{method:'POST'});await refreshThread();await load();}}>Reopen task</button>{/if}<button class="workspace-close" aria-label="Close task workspace" onclick={()=>threadOpen=false}><Icon name="close"/></button></div></header>
      <div class="thread-scroll">
        {#each threadTask.thread.entries as entry}<article class:from-user={entry.author==='user'} class="thread-entry"><small>{entry.author==='user'?'You':entry.author==='coworker'?(threadTask.assignments?.[0]?.employee_name || 'Coworker'):'Task state'} · {entry.kind}</small><p>{entry.body}</p></article>{/each}
        <article class="thread-card"><div><h2>Context</h2><p>Everything below is explicit, ordered, and removable before the next launch.</p></div><button onclick={()=>openComposer(undefined,threadTask)}>Add context</button>{#each threadTask.inputs as input,index}<div class="context-chip"><span>{index+1}. <strong>{input.label}</strong> · {input.kind}</span><button onclick={()=>openComposer(undefined,threadTask)}>Edit</button></div>{:else}<p>No added context yet.</p>{/each}</article>
        {#if !threadTask.plans?.some((plan:any)=>plan.status==='pending'||plan.status==='approved')}<article class="thread-card"><small>PROPOSE A PLAN</small><p>Describe the next bounded approach. It stays pending until you explicitly approve it.</p><form class="thread-form" onsubmit={proposeThreadPlan}><input name="summary" placeholder="Proposed approach" required/><textarea name="milestones" placeholder="Steps, one per line"></textarea><textarea name="acceptance" placeholder="Acceptance, one per line"></textarea><button>Present plan</button></form></article>{/if}
        {#each threadTask.plans as plan}<article class="thread-card"><small>PLAN · VERSION {plan.version} · {plan.status}</small><h2>{plan.summary}</h2><p>{plan.acceptance?.join(' · ') || 'No extra acceptance items recorded.'}</p>{#if plan.status==='pending'}<button class="approve" onclick={async()=>{await approvePlan(plan);await refreshThread();}}>Approve plan v{plan.version}</button>{/if}</article>{/each}
        {#if threadTask.plans?.some((plan:any)=>plan.status==='approved')}<article class="thread-card"><small>EXPLICIT LAUNCH</small><h2>Start the approved work</h2><p>{threadTask.inputs?.some((input:any)=>input.availability!=='available')?'Resolve unavailable context before launch.':threadTask.folders?.length<2?`This task has ${threadTask.folders?.length||0} selected folder. Codex execution requires at least two.`:readiness?.state!=='ready'?`Launch unavailable: ${readiness?.detail || 'Codex is not ready.'}`:'Your approved plan is ready for an explicit Codex request.'}</p><textarea bind:value={launchPrompt} placeholder="Describe the approved work to launch."></textarea><button disabled={Boolean(execution)||readiness?.state!=='ready'||threadTask.folders?.length<2||threadTask.inputs?.some((input:any)=>input.availability!=='available')} onclick={()=>launch(threadTask)}>{execution?'Another execution owns Codex':'Launch Codex'}</button></article>{/if}
        {#each threadTask.thread.decisions as meeting}<article class="thread-card decision-card"><small>DECISION · {meeting.kind} · VERSION {meeting.current_version}</small><h2>{meeting.title}</h2><p><strong>Recommendation:</strong> {meeting.current.recommendation}</p><div class="thread-options">{#each meeting.current.options as option}<span><strong>{option.name}</strong><small>{option.tradeoff}</small></span>{/each}</div><p>{meeting.status==='pending'&&meeting.current.gated_task_ids.includes(threadTask.task_id)?'This task is paused until you decide.':meeting.status==='pending'?'This decision informs this task but does not pause it.':'This decision has been recorded; it no longer blocks this task.'}</p>{#if meeting.status==='pending'}<button class="approve" onclick={async()=>{await approveDecision(meeting);await refreshThread();}}>Approve v{meeting.current_version}</button><button onclick={()=>revisingDecisionId=meeting.decision_id}>Request changes</button>{/if}</article>{/each}
        {#each threadTask.thread.decisions.filter((meeting:any)=>meeting.status==='pending'&&revisingDecisionId===meeting.decision_id) as meeting}<article class="thread-card"><small>REQUEST CHANGES · {meeting.title}</small><form class="thread-form" onsubmit={(event)=>reviseThreadDecision(event,meeting)}><textarea name="feedback" placeholder="What needs to change?" required></textarea><textarea name="recommendation" value={meeting.current.recommendation} required></textarea><textarea name="options" value={meeting.current.options.map((option:any)=>`${option.name} | ${option.tradeoff}`).join('\n')} required></textarea><button>Present revised decision</button></form></article>{/each}
        {#if !threadTask.thread.decisions?.some((meeting:any)=>meeting.status==='pending')}<article class="thread-card"><small>ASK FOR A DECISION</small><p>Use this only when a material choice blocks this task.</p><form class="thread-form" onsubmit={requestThreadDecision}><select name="kind"><option value="technical">Technical decision</option><option value="ui">UI decision</option></select><input name="title" placeholder="Decision to make" required/><textarea name="recommendation" placeholder="Recommendation and why" required></textarea><textarea name="options" placeholder={'One option per line: Name | trade-off\nFocused | faster, less flexible\nFlexible | more setup, easier extension'} required></textarea><button>Ask for decision</button></form></article>{/if}
        {#each threadTask.thread.requests.filter((request:any)=>request.status==='pending') as request}<article class="thread-card attention-card"><small>{request.kind} · coworker needs you</small><h2>{request.summary}</h2><p>{readableRequest(request)}</p><p class="block">{request.blocks}</p>{#if request.decision_id}<button onclick={()=>{const meeting=threadTask.thread.decisions.find((item:any)=>item.decision_id===request.decision_id);if(meeting)document.querySelector('.decision-card')?.scrollIntoView({behavior:motionOff?'auto':'smooth'});}}>Review decision above</button>{:else}<form class="follow-up" onsubmit={(event)=>answerThreadRequest(request,event)}><input name="response" placeholder="Reply to continue the work" required/><button>Send reply</button></form>{/if}</article>{/each}
        {#if threadTask.demo}<article class="thread-card"><small>DEMO</small><h2>{threadTask.demo.evidence?.some((item:any)=>item.status==='accepted')?'Accepted demo evidence':'Demo still needs review'}</h2><p>{threadTask.demo.start_command || 'No demo recipe saved.'}</p></article>{/if}
        {#if threadTask.delivery?.attempts?.[0]}<article class="thread-card"><small>DELIVERY</small><h2>{threadTask.delivery.attempts[0].status}</h2><p>{threadTask.delivery.attempts[0].mode} · delivery remains separately authorized.</p></article>{/if}
        {#each threadTask.thread.team_agreements as agreement}<article class="thread-card agreement"><small>TEAM AGREEMENT · {agreement.provenance}</small><p>{agreement.content}</p></article>{/each}
      </div>
      <form class="thread-compose" onsubmit={(event)=>{event.preventDefault();sendThreadMessage(false);}}><textarea bind:value={threadMessage} placeholder="Reply to your coworker. Ordinary messages stay in this task."></textarea><p>Send a reply for ordinary discussion. Save as a Team agreement only when this message should become durable task guidance.</p><div><button class="agreement-action" type="button" disabled={!threadMessage.trim()} onclick={()=>sendThreadMessage(true)}>Save as Team agreement</button><button class="send-action" disabled={!threadMessage.trim()}>Send reply</button></div></form>
    </div>
  {/if}
  {#if composerOpen && selected}
    <button class="composer-backdrop" aria-label="Close task composer" onclick={()=>composerOpen=false}></button>
    <div class="task-composer" role="dialog" aria-modal="true" aria-label="Task composer" tabindex="-1" use:focusSurface>
      <header><div><p class="eyebrow">{composerTask?'TASK CONTEXT':'TASK BRIEF'}</p><h1>{composerTask?'Add context':'Assign new task'}</h1><p>{composerTask?'Add only explicit context to this task. Scope, assignment, and dispatch do not change here.':'Everything here is saved before dispatch. Assignment never launches a worker.'}</p></div><button type="button" aria-label="Close task composer" onclick={()=>composerOpen=false}><Icon name="close"/></button></header>
      <form onsubmit={saveComposer}>
        {#if composerTask}<input type="hidden" name="title" value={composerTask.title}/><input type="hidden" name="brief_text" value={composerTask.brief_text||''}/><input type="hidden" name="task_instructions" value={composerTask.task_instructions||''}/><input type="hidden" name="employee_id" value={composerEmployeeId}/>{#each composerTask.folders as folder}<input type="hidden" name="folder_ids" value={folder.folder_id}/>{#if folder.is_primary}<input type="hidden" name="primary_folder_id" value={folder.folder_id}/>{/if}{/each}{:else}<label>Objective<input name="title" value="" required placeholder="What should be accomplished?"/></label><label>Brief<textarea name="brief_text" placeholder="Outcome, constraints, and useful background"></textarea></label><label>Task-specific instructions<textarea name="task_instructions" placeholder="Instructions for this task only"></textarea></label><label>Assigned employee<select name="employee_id" bind:value={composerEmployeeId}><option value="">Unassigned</option>{#each staff.filter(person=>person.active) as person}<option value={person.employee_id}>{person.name} · {person.title}{person.active_assignments?.length?` · ${person.active_assignments.length} active tasks`:''}</option>{/each}</select></label><fieldset><legend>Selected project folders</legend>{#each selected.folders.filter((folder:any)=>folder.availability==='available') as folder}<div class="folder-choice"><label><input name="folder_ids" type="checkbox" value={folder.folder_id}/> {folder.display_path}</label><label><input name="primary_folder_id" type="radio" value={folder.folder_id}/> primary</label></div>{/each}</fieldset>{/if}
        <label>Add images or text files<input type="file" multiple accept="image/*,text/*,.json,.md,.csv,.js,.ts,.svelte" onchange={addComposerFiles}/></label>
        <div class="reference-row"><label>Reference a local text or image file<input bind:value={composerFilePath} placeholder="/absolute/path/to/context.txt"/></label><button type="button" onclick={addFileReference}>Add reference</button></div>
        <label>Pasted content<textarea name="pasted_content" placeholder="Paste notes, logs, or other text"></textarea></label>
        <details><summary>Tag project, employee, or task context</summary><fieldset><legend>Projects</legend>{#each projects as project}<label><input type="checkbox" name="tag_project_ids" value={project.project_id}/> {project.name}</label>{/each}</fieldset><fieldset><legend>Employees</legend>{#each staff as person}<label><input type="checkbox" name="tag_employee_ids" value={person.employee_id}/> {person.name}</label>{/each}</fieldset><fieldset><legend>Tasks</legend>{#each board as task}<label><input type="checkbox" name="tag_task_ids" value={task.task_id}/> {task.project_name} · {task.title}</label>{/each}</fieldset></details>
        <section class="input-list" aria-label="Attached and tagged context"><h2>Saved inputs</h2>{#each composerInputs as input,index}<div class:unavailable={input.availability!=='available'}><span><strong>{input.label}</strong><small>{input.kind} · {input.availability}{input.unavailable_reason?` · ${input.unavailable_reason}`:''}</small></span><span class="input-actions">{#if input.kind==='file-reference'}<button type="button" disabled={!composerFilePath.trim()} onclick={()=>relinkComposerInput(index)}>Relink to path above</button>{/if}<button type="button" onclick={()=>removeComposerInput(index)}>Remove</button></span></div>{:else}<p>No attached or tagged context yet.</p>{/each}</section>
        <footer><button type="button" onclick={()=>composerOpen=false}>Cancel</button><button>Save draft</button></footer>
      </form>
    </div>
  {/if}
  {#if inviteOpen}
    <button class="composer-backdrop" aria-label="Close teammate invitation" onclick={()=>inviteOpen=false}></button>
    <div class="invite-sheet" role="dialog" aria-modal="true" aria-label="Invite teammate" tabindex="-1" use:focusSurface>
      <header><div><p class="eyebrow">GROW THE STUDIO · STEP {inviteStep} OF 2</p><h1>{inviteStep===1?'Choose their role':'Choose their Studio identity'}</h1><p>{inviteStep===1?'Start with their name and the work they will lead.':'Pick the complete character family that will represent them in the Studio.'}</p></div><button type="button" aria-label="Close teammate invitation" onclick={()=>inviteOpen=false}><Icon name="close"/></button></header>
      <form onsubmit={(event)=>{event.preventDefault();if(inviteStep===1)inviteStep=2;else createStaff();}}>
        {#if inviteStep===1}
          <label class="invite-name">Their name<input bind:value={inviteName} placeholder="e.g. Mina" required/></label>
          <fieldset class="role-picker"><legend>What should they lead?</legend><div>{#each catalog.positions as position}<button type="button" class:chosen={invitePosition===position.position_id} aria-pressed={invitePosition===position.position_id} onclick={()=>invitePosition=position.position_id}><strong>{position.name}</strong><small>{roleSummaries[position.position_id]}</small></button>{/each}</div></fieldset>
          <footer><p>A role guides how work is described. It does not silently add skills, permissions, or access.</p><span><button type="button" class="secondary" onclick={()=>inviteOpen=false}>Cancel</button><button class="invite-confirm" disabled={!inviteName.trim()}>Choose Studio identity</button></span></footer>
        {:else}
          <fieldset class="identity-picker"><legend>Available Studio identities</legend><p>These are complete character families, not appearance settings. Each can be assigned to one active teammate.</p><div class="identity-grid" role="radiogroup" aria-label="Available Studio identities">{#each availableCharacters as character}<button type="button" class:chosen={inviteCharacter===character.character_id} role="radio" aria-checked={inviteCharacter===character.character_id} onclick={()=>inviteCharacter=character.character_id}><span class="identity-sprite"><Sprite character kind="standing" recipe={character.appearance_recipe}/></span><strong>{character.character_id.replace('studio-character-','Character ')}</strong><small>{inviteCharacter===character.character_id?'Selected':'Available'}</small></button>{/each}</div></fieldset>
          <footer><p>Skills are optional. Add workplace or personal skills later when they are genuinely useful.</p><span><button type="button" class="secondary" onclick={()=>inviteStep=1}>Back</button><button class="invite-confirm" disabled={!inviteCharacter}>Invite {inviteName.trim() || 'teammate'}</button></span></footer>
        {/if}
      </form>
    </div>
  {/if}
  {#if showSettings}<button class="settings-backdrop" aria-label="Dismiss room settings" onclick={()=>showSettings=false} transition:fade={{duration:motionOff?0:100}}></button><div class="settings-popover" role="dialog" aria-modal="true" tabindex="-1" aria-label="Room settings" use:focusSurface={true} in:fly={{x:4,y:4,duration:motionOff?0:150}} out:fade={{duration:motionOff?0:90}}><div class="settings-title"><h2>Room atmosphere</h2><button aria-label="Close room settings" onclick={()=>showSettings=false}><Icon name="close"/></button></div><div class="treatments">{#each ['warm','cool','editorial'] as treatment}<button class:chosen={prefs.map_treatment===treatment} onclick={()=>setTreatment(treatment as 'warm'|'cool'|'editorial')}>{treatment}</button>{/each}</div><label class="toggle"><input type="checkbox" checked={Boolean(prefs.reduced_motion)} onchange={setMotion}/>Reduce motion</label></div>{/if}

</main>

<style>

:global(*){box-sizing:border-box}:global(html),:global(body){margin:0;height:100%;overflow:hidden}:global(body){background:#18181f;color:#595447;font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}:global(button),:global(input),:global(select),:global(textarea){font:inherit}:global(button){cursor:pointer}:global(button:disabled){opacity:.5;cursor:default}:global(button:focus-visible),:global(input:focus-visible),:global(select:focus-visible),:global(textarea:focus-visible){outline:3px solid #b7955d;outline-offset:3px}:global(img){image-rendering:pixelated}:global(h1),:global(h2),:global(p){overflow-wrap:anywhere}
main{height:100dvh;padding:12px 12px 12px 88px;overflow:hidden}.office-layout{height:100%;display:grid;grid-template-columns:minmax(0,1fr) minmax(340px,31.8%);gap:12px}.office-layout.sidebar-closed{grid-template-columns:1fr}.office-stage{position:relative;min-width:0;min-height:0}.studio-sidebar{display:grid;grid-template-rows:minmax(0,66%) minmax(0,1fr);gap:12px;min-height:0}.studio-sidebar[hidden]{display:none}
.appbar{position:fixed;left:14px;top:15px;width:61px;z-index:500}.appbar nav{display:grid;gap:12px}.appbar nav button{position:relative;width:61px;height:68px;padding:15px;background:#272a35;color:#96959a;border:3px solid #424553;border-bottom-color:#22232c;border-right-color:#20212a;box-shadow:inset 2px 2px #555965,inset -2px -2px #232430;clip-path:polygon(5px 0,calc(100% - 5px) 0,100% 5px,100% 100%,0 100%,0 5px)}.appbar nav button:hover,.appbar nav button.active{background:#313542;color:#d8d4cc}.appbar b{position:absolute;right:0;top:0;background:#c56948;width:9px;height:9px;font-size:0}.nav-label{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
.dialogue-frame,.terminal-frame{min-width:0;min-height:0;overflow:hidden;background:#252732;border:3px solid #565a6a;box-shadow:inset 2px 2px #787987,inset -2px -2px #151720;clip-path:polygon(7px 0,calc(100% - 7px) 0,100% 7px,100% calc(100% - 7px),calc(100% - 7px) 100%,7px 100%,0 calc(100% - 7px),0 7px)}.frame-bar{height:40px;display:flex;align-items:center;gap:9px;padding:6px 12px;color:#93949e}.frame-icon{width:19px;height:19px}.frame-caption{font:10px monospace;letter-spacing:.07em;opacity:0}.frame-dots{margin-left:auto;letter-spacing:5px;font-size:24px;line-height:1}.sidebar-close{width:23px;height:23px;padding:3px;border:0;background:none;color:#93949e}
